-- ============================================================
-- Migration 267: page views before our own counter, from Ahrefs.
-- (Applied automatically by the build; nothing to paste.)
--
-- Jonathan, 6 Nov 2026: owners should see their page views from
-- before 5 November too. Our own cookieless counter (page_counts,
-- migration 251) started on 5 Nov 2026. Ahrefs Web Analytics, also
-- cookieless, has counted nomadwise.io since at least mid-2025. Its
-- daily page views per listing page, 1 Jul 2025 to 4 Nov 2026, are
-- loaded here into page_counts (kind 'view'), so the Performance tab,
-- its By month chart and the monthly email show the whole year.
-- Loaded for the spaces that had an owner on 6 Nov 2026; a later
-- owner's history can be loaded the same way with
-- import_page_view_history. Days from 5 Nov on are never touched.
--
-- The note under Performance said "counted by Nomadwise since" the
-- first day in page_counts; it now takes the first Directions day,
-- which is when our own counter started.
-- ============================================================

create or replace function public.import_page_view_history(p_rows jsonb)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare n int;
begin
  -- rows: [[webflow slug, 'YYYY-MM-DD', page views], ...]
  insert into public.page_counts (venue_id, kind, day, n)
  select v.id, 'view', (r ->> 1)::date, sum((r ->> 2)::int)
    from jsonb_array_elements(p_rows) r
    join public.venues v on v.webflow_slug = r ->> 0
   where (r ->> 1)::date < date '2026-11-05'
     and (r ->> 2)::int > 0
   group by v.id, (r ->> 1)::date
  on conflict (venue_id, kind, day) do nothing;
  get diagnostics n = row_count;
  return jsonb_build_object('days_added', n);
end $$;

revoke all on function public.import_page_view_history(jsonb) from public, anon, authenticated;

do $$
declare d text;
begin
  select pg_get_functiondef('public.owner_performance(uuid,integer)'::regprocedure) into d;
  if position('c_from from public.page_counts where kind' in d) = 0 then
    d := replace(d,
      '  select min(day) into c_from from public.page_counts;',
      '  select min(day) into c_from from public.page_counts where kind = ''directions'';');
    if position('c_from from public.page_counts where kind' in d) = 0 then
      raise exception 'owner_performance did not change';
    end if;
    execute d;
  end if;
end $$;

